{{-- Fraud / courier reliability box. Usage: @include('fraud_widget',['fcPhone'=>'01…'|null,'fcInput'=>'#onp']) --}}
@php $fid = 'fc'.substr(md5(uniqid('', true)), 0, 6); @endphp
<div id="{{ $fid }}" class="card" style="margin:8px 0;padding:10px 12px;font-size:12.5px"><div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><b>Courier Reliability</b><span class="fcb" style="color:#6B7280">{{ ($fcPhone ?? null) ? 'Checking…' : 'Enter the customer phone to check.' }}</span><button type="button" class="g fcr" style="margin-left:auto;display:none">Re-check</button></div><div class="fcd" style="margin-top:6px"></div></div>
<script>(function(){var R=document.getElementById('{{ $fid }}'),B=R.querySelector('.fcb'),D=R.querySelector('.fcd'),RB=R.querySelector('.fcr'),inp={!! json_encode($fcInput ?? null) !!},ph={!! json_encode($fcPhone ?? null) !!},last='',t;
function e(s){var d=document.createElement('div');d.textContent=s==null?'':s;return d.innerHTML}
function run(p,f){p=(p||'').replace(/\D/g,'');if(!/^01\d{9}$/.test(p)){B.textContent='Enter the customer phone to check.';B.style.cssText='color:#6B7280';D.innerHTML='';RB.style.display='none';return}
 last=p;B.textContent='Checking…';fetch('/admin/fraud/check?phone='+p+(f?'&fresh=1':''),{headers:{Accept:'application/json'},credentials:'same-origin'}).then(function(r){return r.json()}).then(function(j){if(!j.ok){B.textContent=j.error||'Error';return}
  RB.style.display='';B.innerHTML='<span style="font-weight:700;border-radius:999px;padding:2px 10px;background:'+j.bg+';color:'+j.color+'">'+e(j.label)+'</span> <span style="color:'+j.color+'">'+e(j.bn)+'</span>';
  if(j.risk_level==='unknown'){D.innerHTML='<div style="color:#6B7280">'+e(j.bn)+' — new customers are not treated as risky.'+(j.configured&&!(j.configured.steadfast||j.configured.redx||j.configured.pathao)?' <a href="/admin/fraud">Courier API keys are not set.</a>':'')+'</div>'+own(j);return}
  var c=j.couriers,rows=['steadfast','redx','pathao'].map(function(k){return '<span style="margin-right:12px;text-transform:capitalize">'+k+': <b>'+c[k].delivered+'</b>/'+c[k].total+(c[k].returned?' <span style="color:#B91C1C">(−'+c[k].returned+')</span>':'')+'</span>'}).join('')+(j.pathao_source==='own_parcels'?' <small style="color:#64748B">(Pathao: আমাদের নিজস্ব Pathao পার্সেলের ফলাফল)</small>':j.pathao_source==='network'?' <small style="color:#64748B">(Pathao নেটওয়ার্ক স্কোর)</small>':'');
  D.innerHTML='<div style="display:flex;flex-wrap:wrap;gap:14px"><span>Total Parcels: <b>'+j.total_parcel+'</b></span><span>Delivered: <b style="color:#166534">'+j.total_delivery+'</b></span><span>Returned/Cancelled: <b style="color:#B91C1C">'+j.total_return+'</b></span><span>Success: <b>'+j.success_rate+'%</b></span><span>Return: <b>'+j.return_rate+'%</b></span><span>Risk score: <b>'+j.risk_score+'/100</b></span></div><div style="margin-top:4px;color:#374151">'+rows+'</div>'+own(j)}).catch(function(){B.textContent='Could not check right now.'})}
function own(j){return j.own&&(j.own.delivered||j.own.returned)?'<div style="margin-top:4px;color:#6B7280">Our store history: '+j.own.delivered+' delivered, '+j.own.returned+' returned/cancelled'+(j.own_included?' (included above)':'')+'</div>':''}
RB.onclick=function(){run(last,1)};
if(inp){var i=document.querySelector(inp);if(i){i.addEventListener('input',function(){clearTimeout(t);t=setTimeout(function(){run(i.value)},600)});if(i.value)run(i.value)}}else if(ph)run(ph);})();</script>
